{
  "steps": [
    {
      "step_id": 1,
      "time": "08:00",
      "role": "市气象局",
      "action": "气象监测",
      "description": "气象部门持续监测强降雨天气过程，发布暴雨橙色预警信号，并通报市应急局、市资源规划局及相关区政府，提示山区地质灾害风险显著升高。",
      "resources": [
        { "resource_type": "气象监测设备", "quantity": 1 }
      ]
    },
    {
      "step_id": 2,
      "time": "08:05",
      "role": "市资源规划局",
      "action": "灾害预警",
      "description": "市资源规划局会同市气象局根据气象预报和地质灾害易发程度，联合发布地质灾害气象风险橙色预警，要求相关区县加强巡查排查，做好受威胁群众转移准备。",
      "resources": []
    },
    {
      "step_id": 3,
      "time": "08:10",
      "role": "社区/基层",
      "action": "预警传递",
      "description": "社区/村干部、群测群防员通过广播、敲锣、上门通知等方式，将地质灾害预警信息传递至滑坡隐患点受威胁群众，提醒做好撤离准备。",
      "resources": [
        { "resource_type": "广播设备", "quantity": 1 },
        { "resource_type": "锣", "quantity": 2 }
      ]
    },
    {
      "step_id": 4,
      "time": "08:15",
      "role": "社区/基层",
      "action": "险情巡查",
      "description": "社区/村干部和群测群防员对滑坡隐患点开展巡查监测，发现坡体出现明显裂缝、树木倾斜等滑坡前兆，立即上报街道办事处和区自然资源部门。",
      "resources": []
    },
    {
      "step_id": 5,
      "time": "08:20",
      "role": "社区/基层",
      "action": "灾情上报",
      "description": "社区/村将滑坡险情信息上报至街道办事处及区应急管理局、区自然资源和规划局，报告内容包括险情发生时间、地点、类型、规模、受威胁人数及发展趋势等。",
      "resources": []
    },
    {
      "step_id": 6,
      "time": "08:25",
      "role": "市应急局",
      "action": "会商研判",
      "description": "市应急局和市资源规划局接到地质灾害报告后，相互通报信息并开展会商研判，对灾情进行核实，按相关规定向省自然资源厅、省应急厅、市委市政府报告，及时续报。",
      "resources": []
    },
    {
      "step_id": 7,
      "time": "08:30",
      "role": "应急指挥部",
      "action": "启动响应",
      "description": "西安市立即启动《西安市突发地质灾害应急预案》Ⅱ级响应，成立市突发地质灾害应急指挥部和现场指挥部，命令市防灾减灾救灾工作委员会各成员单位按照预案职责指导蓝田县开展人员疏散安置、应急救援、交通疏导、警戒防控等工作。",
      "resources": []
    },
    {
      "step_id": 8,
      "time": "08:35",
      "role": "应急指挥部",
      "action": "统一指挥",
      "description": "市突发地质灾害应急指挥部统一指挥协调各工作组行动，下设综合协调组、抢险救援组、医疗救护组、交通管制组、秩序稳控组、后勤保障和善后安置组、调查评估组等，明确各组职责分工。",
      "resources": []
    },
    {
      "step_id": 9,
      "time": "08:40",
      "role": "应急指挥部",
      "action": "应急队伍集结",
      "description": "市应急局调集市消防救援支队、中国安能二局厦门分公司、厦门警备区、武警厦门支队等应急救援队伍携带生命探测仪、破拆工具、挖掘机等装备赶赴现场集结。",
      "resources": [
        { "resource_type": "生命探测仪", "quantity": 2 },
        { "resource_type": "破拆工具", "quantity": 5 },
        { "resource_type": "挖掘机", "quantity": 3 },
        { "resource_type": "消防车", "quantity": 4 }
      ]
    },
    {
      "step_id": 10,
      "time": "08:45",
      "role": "区政府",
      "action": "先期处置",
