      "resources": [
        { "resource_type": "警示标志", "quantity": 10 },
        { "resource_type": "警戒带", "quantity": 5 }
      ]
    },
    {
      "step_id": 12,
      "time": "08:55",
      "role": "社区/基层",
      "action": "危险区排查",
      "description": "社区/村干部配合市住房局、市建设局、市资源规划局对滑坡危险区内房屋、道路及受威胁群众进行全面排查，逐户核实人员信息，确定需转移人员名单。",
      "resources": []
    },
    {
      "step_id": 13,
      "time": "09:00",
