      "resources": []
    },
    {
      "step_id": 16,
      "time": "09:15",
      "role": "疏散引导组",
      "action": "人员转移引导",
      "description": "村干部、监测员带领志愿者，通过敲锣发出撤离信号和广播通知受威胁群众，按照预定的安全撤离路线，引导大家有序转移到安全区域。特别安排专人照顾老弱病残孕等特殊人群。",
